import json, io, sys, importlib.util, os
HERE = os.path.dirname(os.path.abspath(__file__))
spec = importlib.util.spec_from_file_location('cal', os.path.join(HERE, '..', 'cin2', '_cal.py'))
cal = importlib.util.module_from_spec(spec); spec.loader.exec_module(cal)
sys.stdout = open(1, 'w', encoding='utf-8', closefd=False)

def J(y, m, d): return cal.jdn_jul(y, m, d)
def D(jd): return '%04d-%02d-%02d' % cal.jul(jd)

# ---------- tarih hesaplari (Jülyen) ----------
T_KUCA_FETIH = D(J(648, 12, 20) + 30)            # 貞觀二十二年閏十二月丁丑朔
assert cal.gz(J(649, 1, 19)) == '丁丑' and T_KUCA_FETIH == '0649-01-19'
T_PRISONERS = D(J(649, 1, 19) + 34)              # 二十三年春正月辛亥
assert cal.gz(J(649, 1, 19) + 34) == '辛亥'
T_ATAMA = [D(x) for x in cal.find(647, 12, '戊寅')][-1]   # 貞觀二十一年十二月戊寅
T_PISHA = [D(x) for x in cal.find(675, 1, '丙寅')][0]     # 上元二年正月丙寅
T_SHULE673 = [D(x) for x in cal.find(673, 12, '丙午')]    # 咸亨四年十二月丙午
T_WEI437 = [D(x) for x in cal.find(437, 11, '甲申')][0]   # 太延三年十一月甲申
T_TIBET670 = '0670-04-25'                                  # 咸亨元年夏四月 (ay basi)
T_RECOVER692 = '0692-11-14'                                # 長壽元年冬十月 (ay basi)
def hijri(y, m, d): return D(d + int(29.5 * (m - 1) + 0.5 + 1e-9) + (y - 1) * 354 + (3 + 11 * y) // 30 + 1948439)
T_H451 = hijri(451, 1, 1)
print('tarihler:', T_KUCA_FETIH, T_PRISONERS, T_ATAMA, T_PISHA, T_SHULE673, T_WEI437, T_H451)

