def dump(x): return json.dumps(x, ensure_ascii=False, indent=1)

# kunye kronoloji alanlarini tamamla
for k in KUNYE:
    for m in k['kronoloji']:
        m.setdefault('gun', m['t'])

# sinir maddeleri (yama devirleri)
SINIR = []
for y in YAMA:
    s = y['s']
    for i in range(1, len(s)):
        sl = s[i]
        if not sl['_b']:
            continue
        tur = sl['_tur']
        winner = sl['_winner']; loser = sl['_loser']
        taraflar = [x for x in [winner, loser] if x and x != '__BOSLUK__']
        devlet = winner if winner else loser
        kes = sl['_kes'] or 'yil'
        dd = '%s (atlas yerleşimi «%s») %s gününde %s egemenliğine geçti: %s.' % (y['yer_tr'], y['ad'], sl['f'], winner if winner else '__BOSLUK__ (sahip belirsiz)', sl['_b'])
        if not winner:
            dd = '%s (atlas yerleşimi «%s») %s gününde %s egemenliğinden çıktı; kalıcı sahip belirsiz (BOŞLUK dilimi): %s.' % (y['yer_tr'], y['ad'], sl['f'], loser, sl['_b'])
        item = dict(t=sl['f'], devlet=devlet, taraflar=taraflar, b=sl['_b'], tur=tur, onem=2, dunya=1, kapsam='dis',
                    yer=y['yer_tr'], yer_id=y['ad'], etiket=['toprak-degisimi', 'konu-askeri', 'dogu-500-1281'], d=dd,
                    kaynak=sl['kaynak'], sinir_id=[], kesinlik=kes)
        if sl['_ic']: item['ic_not'] = sl['_ic']
        SINIR.append(item)

# bosluk dilimi: devir ciktisi (0819 giris, 0751 cikis) — 0819'u samani slice ureter (winner samani). 0751 kayip: yukarida.

# yama temiz kayit
YAMA_OUT = []
for y in YAMA:
    r = dict(ad=y['ad'], mevcut_zincir_basi=y['mevcut_zincir_basi'], aciklama='YAMA GEREKLİ: s: önekini ekle (ilk dilim f ' + y['s'][0]['f'] + ')',
             s_onek=[dict(f=s['f'], t=s['t'], d=s['d'], kesinlik=s['kesinlik'], kaynak=s['kaynak']) for s in y['s']])
    if y['devam_gerekli']: r['devam_gerekli'] = y['devam_gerekli']
    YAMA_OUT.append(r)

def wjs(dosya, ust, glob, data):
    with open(os.path.join(HERE, dosya), 'w', encoding='utf-8') as f:
        f.write('// ' + ust + '\nwindow.' + glob + ' = ' + dump(data) + ';\n')

wjs('kunye_yeni.js', 'kunye_yeni.js — DOGU BOZKIR-3 yeni künyeler (kuca, khotan, kasgar-shule, fergana-dayuan, cac-tudun, buhara-hudat, kirgiz-erken)', 'DOGU_KUNYE_BOZKIR3', KUNYE)
wjs('kronoloji_cok_dogu_bozkir3.js', 'kronoloji_cok_dogu_bozkir3.js — DOGU 500-1281 / BOZKIR-3 anlatı maddeleri (Jülyen; Çin ganzhi günleri hesapla çevrilmiştir)', 'KRONOLOJI_COK_DOGU_BOZKIR3', KRON)
wjs('kronoloji_sinir_dogu_bozkir3.js', 'kronoloji_sinir_dogu_bozkir3.js — DOGU 500-1281 / BOZKIR-3 yerleşim sahip değişimi (s: kırılması) maddeleri, Değişmez 2 evreni', 'KRONOLOJI_SINIR_DOGU_BOZKIR3', SINIR)
wjs('yerlesimler_dogu_bozkir3.js', 'yerlesimler_dogu_bozkir3.js — DOGU BOZKIR-3 yeni yerleşim (0). Mevcut yerleşimler için yama_bozkir3.js', 'YERLESIMLER_DOGU_BOZKIR3', [])
wjs('yama_bozkir3.js', 'yama_bozkir3.js — MEVCUT atlas yerleşimlerine eklenecek s: önekleri (yama aracı girdisi)', 'YAMA_DOGU_BOZKIR3', YAMA_OUT)
print('kunye', len(KUNYE), 'kron', len(KRON), 'sinir', len(SINIR), 'yama', len(YAMA_OUT), 'dilim', sum(len(y['s_onek']) for y in YAMA_OUT))
